import org.springframework.web.reactive.function.client.WebClient;
import org.springframework.web.client.RestTemplate;
import reactor.core.publisher.Mono;

public class HttpClientExample {
    private static final WebClient webClient = WebClient.create("https://api.example.com");
    private static final RestTemplate restTemplate = new RestTemplate();

    public static void main(String[] args) {
        String result1 = callApiWithWebClient();
        System.out.println("WebClient Response: " + result1);

        String result2 = callApiWithRestTemplate();
        System.out.println("RestTemplate Response: " + result2);
    }

    private static String callApiWithWebClient() {
        return webClient.get()
                .uri("/data")
                .retrieve()
                .bodyToMono(String.class)
                .block(); 
    }

    private static String callApiWithRestTemplate() {
        return restTemplate.getForObject("https://api.example.com/data", String.class);
    }
}
