package test.one;

public abstract class One {

    protected abstract void whatever();

    public void run() {
        whatever();
    }
}

package test.two;

import test.one.One;

public class Three {

    public static void main(String[] args) {
        One one = new One() {
            @Override
            protected void whatever() {
                System.out.println("Do whatever..");
            }
        };
        one.whatever(); // Error
    }
}

