import org.junit.jupiter.api.Test
import org.mockito.invocation.InvocationOnMock
import org.mockito.stubbing.Answer

import static org.mockito.ArgumentMatchers.any
import static org.mockito.ArgumentMatchers.eq
import static org.mockito.Mockito.*

class DSLMock {
    def mock

    DSLMock() {
        this.mock = mock(DSL.class)

        doAnswer(new Answer<Void>() {
            @Override
            Void answer(InvocationOnMock invocationOnMock) throws Throwable {
                throw new AbortException((String) invocationOnMock.getArguments()[0])
            }
        }).when(mock).invokeMethod(eq("error"), any())
    }
}

class DSLMockTest {
    @Test
    void testMockBehavior() {
        def dslMock = new DSLMock()

        try {
            dslMock.mock.invokeMethod("error", "Some error message")
        } catch (AbortException e) {
            assert e.message == "Some error message"
        }
    }
}
