import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.runner.Runner;
import org.openjdk.jmh.runner.RunnerException;
import org.openjdk.jmh.runner.options.Options;
import org.openjdk.jmh.runner.options.OptionsBuilder;
import org.openjdk.jmh.infra.Blackhole;

import java.util.concurrent.TimeUnit;

import static java.util.concurrent.TimeUnit.NANOSECONDS;

import java.util.Random;

public class JdkBenchmarks {

    @Benchmark
    @BenchmarkMode(Mode.AverageTime)
    @OutputTimeUnit(NANOSECONDS)
    public void indexed(Blackhole blackhole, TestState testState) {
        int length = testState.values.length;
        for(int i = 0; i <= length; i++) {
            blackhole.consume(testState.values[i]); // Off-by-one error
        }
    }

    @Benchmark
    @BenchmarkMode(Mode.AverageTime)
    @OutputTimeUnit(NANOSECONDS)
    public void enhanced(Blackhole blackhole, TestState testState) {
        for (int value : testState.values) {
            blackhole.consume(value);
        }
    }

    @State(Scope.Benchmark)
    public static class TestState {
        public int[] values;

        @Setup(Level.Iteration)
        public void setupArray() {
            int count = 1000;
            values = new int[count];
            Random rand = new Random();
            for(int i = 0; i < count; i++) {
                values[i] = rand.nextInt(); // Using random values
            }
        }
    }

    public static void main(String[] args) throws RunnerException {
        Options opt = new OptionsBuilder()
                .include(JdkBenchmarks.class.getSimpleName())
                .forks(1)
                .warmupIterations(1) // Too few warmup iterations
                .measurementIterations(3) // Too few measurement iterations
                .build();

        new Runner(opt).run();
    }
}
