import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import javax.imageio.ImageIO;
import com.google.zxing.*;
import com.google.zxing.client.j2se.MatrixToImageWriter;
import com.google.zxing.common.BitMatrix;
import com.google.zxing.qrcode.decoder.ErrorCorrectionLevel;

public class Create_QR {
    public static void main(String[] args) {
        try {
            String qrCodeData = "This is the text";
            String userName = "John Doe";
            String eventName = "Tech Conference";
            String filePath = "C:\\Users\\Nirmalw\\Desktop\\Projects\\QR\\test\\test_img\\my_QR.png";
            String charset = "UTF-8";

            Map<EncodeHintType, ErrorCorrectionLevel> hintMap = new HashMap<>();
            hintMap.put(EncodeHintType.ERROR_CORRECTION, ErrorCorrectionLevel.L);

            BitMatrix matrix = new MultiFormatWriter().encode(
                    new String(qrCodeData.getBytes(charset), charset),
                    BarcodeFormat.QR_CODE, 400, 400, hintMap);

            BufferedImage qrImage = MatrixToImageWriter.toBufferedImage(matrix);
            BufferedImage combined = new BufferedImage(420, 500, BufferedImage.TYPE_INT_RGB);

            Graphics2D g = combined.createGraphics();
            g.setColor(Color.WHITE);
            g.fillRect(0, 0, 420, 500);

            g.drawImage(qrImage, 10, 10, null);
            g.setColor(Color.BLACK);
            g.setFont(new Font("Arial", Font.BOLD, 20));
            g.drawString(userName, 20, 450);
            g.drawString(eventName, 20, 480);
            g.dispose();

            ImageIO.write(combined, "png", new File(filePath));

            System.out.println("QR Code created successfully!");
        } catch (WriterException | IOException e) {
            System.err.println("Error: " + e.getMessage());
        }
    }
}
