import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.HashMap;
import java.util.Map;

public class JSONConverter {
    public static void main(String[] args) {
        Map<String, Integer> fields = new HashMap<>();
        fields.put("test_first", 1);
        fields.put("test_second", 2);

        ObjectMapper mapper = new ObjectMapper();
        Map<String, Integer> transformedMap = new HashMap<>();

        for (Map.Entry<String, Integer> entry : fields.entrySet()) {
            String key = toCamelCase(entry.getKey());
            transformedMap.put(key, entry.getValue());
        }

        try {
            String json = mapper.writeValueAsString(transformedMap);
            System.out.println(json);
        } catch (JsonProcessingException e) {
            e.printStackTrace();
        }
    }

    private static String toCamelCase(String str) {
        String[] parts = str.split("_");
        StringBuilder camelCaseString = new StringBuilder(parts[0]);
        for (int i = 1; i < parts.length; i++) {
            camelCaseString.append(parts[i].substring(0, 1).toUpperCase()).append(parts[i].substring(1));
        }
        return camelCaseString.toString();
    }
}
