class MainActivity : FlutterActivity() {

    private val CHANNEL = "signInChannel"
    private var authResult = registerForActivityResult(PianoIdAuthResultContract()) { r ->
        when (r) {
            null -> { }
            is PianoIdAuthSuccessResult -> {
                val token = r.token
                val isNewUserRegistered = r.isNewUser
                if (token != null) {
                    if (token.emailConfirmationRequired) {
                    }
                }
            }
            is PianoIdAuthFailureResult -> {
                val e = r.exception
            }
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        MethodChannel(flutterEngine!!.dartExecutor.binaryMessenger, CHANNEL).setMethodCallHandler { call, result ->
            if (call.method == "testSignIn") {
                try {
                    authResult.launch(PianoId.signIn())
                    result.success("Started sign-in process")
                } catch (e: Exception) {
                    val text = e.message ?: "Unknown error"
                    Toast.makeText(applicationContext, text, Toast.LENGTH_SHORT).show()
                    result.error("SIGN_IN_ERROR", text, null)
                }
            } else {
                result.notImplemented()
            }
        }
    }
}
