import com.sun.source.tree.*;
import com.sun.source.util.Trees;
import com.sun.tools.javac.api.JavacTrees;
import com.sun.tools.javac.code.Type;
import com.sun.tools.javac.processing.JavacProcessingEnvironment;
import com.sun.tools.javac.tree.JCTree;

import javax.annotation.processing.AbstractProcessor;
import javax.annotation.processing.RoundEnvironment;
import javax.annotation.processing.SupportedAnnotationTypes;
import javax.annotation.processing.SupportedSourceVersion;
import javax.lang.model.SourceVersion;
import javax.lang.model.element.Element;
import javax.lang.model.element.TypeElement;
import java.util.Set;

@SupportedAnnotationTypes("*")
@SupportedSourceVersion(SourceVersion.RELEASE_17)
public class SwitchExpressionTypeProcessor extends AbstractProcessor {

    private Trees trees;

    @Override
    public synchronized void init(javax.annotation.processing.ProcessingEnvironment processingEnv) {
        super.init(processingEnv);
        this.trees = JavacTrees.instance(processingEnv);
    }

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (Element element : roundEnv.getRootElements()) {
            TreePath path = trees.getPath(element);
            if (path != null) {
                new TreeScanner<Void, Void>() {
                    @Override
                    public Void visitMethod(MethodTree methodTree, Void unused) {
                        BlockTree blockTree = methodTree.getBody();
                        if (blockTree != null) {
                            for (StatementTree statementTree : blockTree.getStatements()) {
                                if (statementTree.getKind() == Tree.Kind.SWITCH) {
                                    SwitchTree switchTree = (SwitchTree) statementTree;
                                    ExpressionTree switchTreeExpression = switchTree.getExpression();
                                    if (switchTreeExpression instanceof JCTree.JCExpression) {
                                        Type type = ((JCTree.JCExpression) switchTreeExpression).type;
                                        if (type != null) {
                                            System.out.println("Switch Expression Type: " + type.toString());
                                        }
                                    }
                                }
                            }
                        }
                        return super.visitMethod(methodTree, unused);
                    }
                }.scan(path.getCompilationUnit(), null);
            }
        }
        return false;
    }
}
