import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.chart.NumberAxis;
import javafx.scene.chart.XYChart;
import javafx.stage.Stage;
import java.util.ArrayList;
import java.util.List;

public class ScatterChartExample extends Application {

    private List<Double> r = new ArrayList<>();
    private List<Double> nodes = new ArrayList<>();

    @Override
    public void start(Stage primaryStage) {
        populateData();
        createScatterChart();
    }

    private void populateData() {
        for (int i = 0; i < 10; i++) {
            r.add(10.0 + i * 2);
            nodes.add(i * 36.0);
        }
    }

    public void createScatterChart() {
        final NumberAxis xAxis = new NumberAxis();
        final NumberAxis yAxis = new NumberAxis();

        final XYChart<Number, Number> smoothedChart = new XYChart<>(xAxis, yAxis);

        XYChart.Series<Number, Number> series1 = new XYChart.Series<>();
        XYChart.Series<Number, Number> series2 = new XYChart.Series<>();

        for (int i = 0; i < r.size(); i++) {
            double x = r.get(i) * Math.cos(Math.toRadians(nodes.get(i)));
            double y = r.get(i) * Math.sin(Math.toRadians(nodes.get(i)));
            series1.getData().add(new XYChart.Data<>(x, y));

            if (i < r.size() - 1) {
                double xNext = r.get(i + 1) * Math.cos(Math.toRadians(nodes.get(i + 1)));
                double yNext = r.get(i + 1) * Math.sin(Math.toRadians(nodes.get(i + 1)));
                series2.getData().add(new XYChart.Data<>(xNext, yNext));
            }
        }

        smoothedChart.getData().add(series1);
        smoothedChart.getData().add(series2);

        Stage stage = new Stage();
        Scene scene = new Scene(smoothedChart, 800, 600);
        stage.setScene(scene);
        stage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}
