    static class AnimatedRect extends Rectangle {

        SimpleObjectProperty<Timeline> timeline = new SimpleObjectProperty<>();

        public AnimatedRect(double width, double height) {
            super(width, height);
            setFill(color1.get());

            color1.addListener((obs, o, v) -> restartAnimation());
            color2.addListener((obs, o, v) -> restartAnimation());

            sceneProperty().addListener((obs, o, n) -> {
                if (n != null && timeline.get() != null) {
                    timeline.get().play();
                } else if (timeline.get() != null) {
                    timeline.get().stop();
                }
            });
        }

        void restartAnimation() {
            if (timeline.get() != null) {
                timeline.get().stop();
            }
            timeline.set(createTimeline());
            timeline.get().play();
        }

        Timeline createTimeline() {
            var timeline = new Timeline(
                new KeyFrame(Duration.millis(0),
                    new KeyValue(fillProperty(), color1.getValue())
