import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.servlet.LocaleResolver;
import org.springframework.web.servlet.handler.HandlerInterceptorAdapter;
import org.springframework.web.servlet.i18n.CookieLocaleResolver;
import org.springframework.web.servlet.i18n.LocaleChangeInterceptor;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;

@Configuration
public class LocaleConfig {

    private static final List<Locale> ALLOWED_LOCALES = Arrays.asList(Locale.ENGLISH, new Locale("hi"));

    @Bean
    public LocaleResolver localeResolver() {
        CookieLocaleResolver resolver = new CookieLocaleResolver();
        resolver.setDefaultLocale(Locale.ENGLISH);
        return resolver;
    }

    @Bean
    public LocaleChangeInterceptor localeChangeInterceptor() {
        return new LocaleChangeInterceptor() {
            @Override
            public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
                String newLocale = request.getParameter(getParamName());
                if (newLocale != null) {
                    Locale locale = Locale.forLanguageTag(newLocale);
                    if (!ALLOWED_LOCALES.contains(locale)) {
                        throw new IllegalArgumentException("Invalid locale: " + newLocale);
                    }
                }
                return super.preHandle(request, response, handler);
            }
        };
    }
}
