import net.sf.jasperreports.engine.JRException;
import net.sf.jasperreports.engine.JasperCompileManager;
import net.sf.jasperreports.engine.JasperFillManager;
import net.sf.jasperreports.engine.JasperPrint;
import net.sf.jasperreports.engine.JasperReport;
import net.sf.jasperreports.engine.JasperExportManager;

import java.awt.Image;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import javax.imageio.ImageIO;

public class S3JasperReport {
    public static void main(String[] args) throws JRException, IOException {
        AmazonS3 s3Client = AmazonS3ClientBuilder.defaultClient();
        String bucketName = "your-bucket";
        String key = "image_name.jpg";

        S3Object s3Object = s3Client.getObject(bucketName, key);
        Image image = ImageIO.read(new ByteArrayInputStream(s3Object.getObjectContent().readAllBytes()));

        Map<String, Object> params = new HashMap<>();
        params.put("imageParam", image);

        JasperReport jasperReport = JasperCompileManager.compileReport("report_template.jrxml");
        JasperPrint jasperPrint = JasperFillManager.fillReport(jasperReport, params);

        JasperExportManager.exportReportToPdfFile(jasperPrint, "output.pdf");
    }
}
