import de.hybris.platform.commercewebservicescommons.dto.user.CustomerData;
import de.hybris.platform.commercewebservicescommons.dto.TestListWsDTO;
import de.hybris.platform.commerceservices.customer.CustomerFacade;
import de.hybris.platform.commercefacades.user.UserFacade;
import de.hybris.platform.webservicescommons.mapping.DataMapper;
import de.hybris.platform.webservicescommons.oauth2.OAuthCustomerService;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.access.annotation.Secured;
import org.springframework.web.bind.annotation.*;

import javax.annotation.Resource;

@RestController
@RequestMapping("/{baseSiteId}/test")
public class CustomTestController {

    @Resource
    private CustomerFacade customerFacade;

    @Resource
    private UserFacade userFacade;

    @Resource
    private DataMapper dataMapper;

    @Resource
    private OAuthCustomerService oAuthCustomerService;

    @Secured({ "ROLE_CUSTOMERGROUP", "ROLE_TRUSTED_CLIENT", "ROLE_CUSTOMERMANAGERGROUP" })
    @GetMapping
    @ResponseBody
    @ApiBaseSiteIdAndUserIdParam
    public TestListWsDTO getTest(@RequestParam(required = false, defaultValue = "DEFAULT") final String fields) {
        String userId = userFacade.getCurrentCustomerUid();
        if (userFacade.isAnonymousUser() || userId == null || userId.isEmpty()) {
            throw new AccessDeniedException("Anonymous user is not allowed");
        }

        CustomerData customerData = customerFacade.getCurrentCustomer();
        if (customerData == null) {
            throw new AccessDeniedException("Customer data is not available");
        }

        return dataMapper.map(customerData, TestListWsDTO.class, fields);
    }
}
