import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.dataformat.xml.ser.ToXmlGenerator;
import com.fasterxml.jackson.databind.ser.std.StdSerializer;
import java.io.IOException;
import java.util.Iterator;

public class ItemSerializer extends StdSerializer<Item> {

    public ItemSerializer() {
        this(null);
    }

    public ItemSerializer(Class<Item> t) {
        super(t);
    }

    @Override
    public void serialize(Item item, JsonGenerator gen, SerializerProvider provider) throws IOException {
        ToXmlGenerator xmlGen = (ToXmlGenerator) gen;
        xmlGen.writeStartObject();

        xmlGen.writeStringField("SNO", item.getSNo());
        xmlGen.writeNumberField("Weight", item.getWeight());

        Iterator<String> aIter = item.getAList().iterator();
        Iterator<String> bIter = item.getBList().iterator();

        while (aIter.hasNext() || bIter.hasNext()) {
            if (aIter.hasNext()) xmlGen.writeStringField("A", aIter.next());
            if (bIter.hasNext()) xmlGen.writeStringField("B", bIter.next());
        }

        xmlGen.writeEndObject();
    }
}
import com.fasterxml.jackson.databind.annotation.JsonSerialize;
import com.fasterxml.jackson.dataformat.xml.annotation.JacksonXmlProperty;
import com.fasterxml.jackson.dataformat.xml.annotation.JacksonXmlRootElement;

import java.util.List;

@JacksonXmlRootElement(localName = "Item")
@JsonSerialize(using = ItemSerializer.class)
public class Item {

    @JacksonXmlProperty(localName = "SNO")
    private String sNo;

    @JacksonXmlProperty(localName = "Weight")
    private Float weight;

    private List<String> aList;
    private List<String> bList;

    public String getSNo() { return sNo; }
    public Float getWeight() { return weight; }
    public List<String> getAList() { return aList; }
    public List<String> getBList() { return bList; }

    public void setSNo(String sNo) { this.sNo = sNo; }
    public void setWeight(Float weight) { this.weight = weight; }
    public void setAList(List<String> aList) { this.aList = aList; }
    public void setBList(List<String> bList) { this.bList = bList; }
}
