import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.DeserializationContext;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.io.IOException;
import java.text.ParseException;
import java.util.Date;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class StringToDateDeserializerTest {

    private final StringToDateDeserializer deserializer = new StringToDateDeserializer();

    @Test
    void testDeserializeValidDate() throws IOException, ParseException {
        JsonParser mockParser = mock(JsonParser.class);
        DeserializationContext mockContext = mock(DeserializationContext.class);

        when(mockParser.getText()).thenReturn("2024-03-12T15:30:00Z");

        Date result = deserializer.deserialize(mockParser, mockContext);
        assertNotNull(result);
    }

    @Test
    void testDeserializeEmptyString() throws IOException {
        JsonParser mockParser = mock(JsonParser.class);
        DeserializationContext mockContext = mock(DeserializationContext.class);

        when(mockParser.getText()).thenReturn("");

        Date result = deserializer.deserialize(mockParser, mockContext);
        assertNull(result);
    }

    @Test
    void testDeserializeInvalidDate() throws IOException {
        JsonParser mockParser = mock(JsonParser.class);
        DeserializationContext mockContext = mock(DeserializationContext.class);

        when(mockParser.getText()).thenReturn("invalid-date");

        assertThrows(MyCustomException.class, () -> deserializer.deserialize(mockParser, mockContext));
    }
}
