import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.security.SecureRandom;
import java.util.Base64;

public class AESEncryption {
    public static void main(String[] args) throws Exception {
        byte[] keyValue = Files.readAllBytes(Paths.get("/home/debashishd/Downloads/s_key"));

        byte[] keyBytes = new byte[32];
        System.arraycopy(keyValue, 0, keyBytes, 0, Math.min(keyValue.length, 32));

        SecretKeySpec secretKey = new SecretKeySpec(keyBytes, "AES");
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");

        byte[] iv = new byte[16];
        new SecureRandom().nextBytes(iv);
        IvParameterSpec ivSpec = new IvParameterSpec(iv);

        cipher.init(Cipher.ENCRYPT_MODE, secretKey, ivSpec);
        String testMessage = "Hello this is Roxane";
        byte[] encryptedBytes = cipher.doFinal(testMessage.getBytes(StandardCharsets.UTF_8));
        String encryptedValue = Base64.getEncoder().encodeToString(encryptedBytes);
        String ivString = Base64.getEncoder().encodeToString(iv);

        System.out.println("Encrypted value: " + encryptedValue);

        Cipher decryptCipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        decryptCipher.init(Cipher.DECRYPT_MODE, secretKey, new IvParameterSpec(Base64.getDecoder().decode(ivString)));
        byte[] decryptedBytes = decryptCipher.doFinal(Base64.getDecoder().decode(encryptedValue));
        String decryptedResult = new String(decryptedBytes, StandardCharsets.UTF_8);

        System.out.println("Decrypted value: " + decryptedResult);
    }
}
