package com.xerox;
import java.io.BufferedWriter;
import java.io.FileOutputStream;
import java.io.OutputStreamWriter;
import java.nio.charset.StandardCharsets;
import java.time.LocalDateTime;

import org.thymeleaf.TemplateEngine;
import org.thymeleaf.context.Context;
import org.thymeleaf.templatemode.TemplateMode;
import org.thymeleaf.templateresolver.ClassLoaderTemplateResolver;

public class TestThymeleafUTF8 {
    public static void main(String[] args) {
        try {
               TemplateEngine templateEngine = new TemplateEngine();
                ClassLoaderTemplateResolver resolver = new ClassLoaderTemplateResolver();
                resolver.setCharacterEncoding("UTF-8");     
                resolver.setTemplateMode(TemplateMode.XML);  // Ensure XML template mode
                templateEngine.setTemplateResolver(resolver);
                Context ct = new Context();             

                // These variables should hold the correct UTF-8 characters, 
                // not incorrectly encoded characters.
                ct.setVariable("TEST_AR", "????? ??????");
                ct.setVariable("TEST_HE", "???? ????");
                ct.setVariable("TEST_CN", "?????");
                ct.setVariable("currentDate", LocalDateTime.now().toString());

                BufferedWriter out = new BufferedWriter(new OutputStreamWriter(new FileOutputStream("test_output.xml"), StandardCharsets.UTF_8));  

                templateEngine.process("test_template.xml", ct, out);  // Use XML extension for proper encoding
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
