@Configuration
public class ElasticsearchConfig {

    @Bean
    public RestHighLevelClient client() throws Exception {
        Path certificatePath = Paths.get("path/to/your/certificate.crt");
        char[] password = "password".toCharArray();

        SSLContext sslContext = SSLContexts.custom()
            .loadTrustMaterial(certificatePath.toFile(), password)
            .build();

        HttpHost host = new HttpHost("localhost", 9700, "https");
        RestClientBuilder builder = RestClient.builder(host)
            .setHttpClientConfigCallback(httpClientBuilder -> httpClientBuilder.setSSLContext(sslContext));

        return new RestHighLevelClient(builder);
    }

    @Bean
    public ElasticsearchRestTemplate elasticsearchRestTemplate(RestHighLevelClient client) {
        return new ElasticsearchRestTemplate(client);
    }
}
