class MyCanvas extends JComponent {
    private static final double SCALE_FACTOR = getScaleFactor();

    @Override
    protected void paintComponent(Graphics g) {
        if (g instanceof Graphics2D g2) {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setFont(Font.decode("Times New Roman-26"));
            g2.drawString("The poorly-scaled cake is a lie.", 70, 40);
            g2.setStroke(new BasicStroke(2.3f));
            g2.draw(new Line2D.Double(420, 10, 425, 70));

            Image I = createScalingAwareBuffer(getWidth(), getHeight());
            Graphics2D g2_ = (Graphics2D) I.getGraphics();
            g2_.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2_.setColor(Color.BLACK);
            g2_.setFont(Font.decode("Times New Roman-26"));
            g2_.drawString("The poorly-scaled cake is a lie.", 70, 40);
            g2_.setStroke(new BasicStroke(2.3f));
            g2_.draw(new Line2D.Double(420, 10, 425, 70));
            g2_.dispose();
            g2.drawImage(I, 0, 130, null);
        }
    }

    private static Image createScalingAwareBuffer(int width, int height) {
        int scaledWidth = (int) (width * SCALE_FACTOR);
        int scaledHeight = (int) (height * SCALE_FACTOR);
        BufferedImage img = new BufferedImage(scaledWidth, scaledHeight, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2 = img.createGraphics();
        g2.scale(SCALE_FACTOR, SCALE_FACTOR);
        g2.dispose();
        return img;
    }

    private static double getScaleFactor() {
        GraphicsEnvironment ge = GraphicsEnvironment.getLocalGraphicsEnvironment();
        GraphicsDevice gd = ge.getDefaultScreenDevice();
        GraphicsConfiguration gc = gd.getDefaultConfiguration();
        AffineTransform tx = gc.getDefaultTransform();
        return tx.getScaleX();
    }
}
