import org.apache.poi.hssf.usermodel.HSSFWorkbook;
import org.apache.poi.ss.usermodel.*;

import java.io.FileOutputStream;
import java.io.OutputStream;

public class ExcelExport {
    public static void main(String[] args) {
        try (
            OutputStream os = new FileOutputStream("test.xls");
            Workbook wb = new HSSFWorkbook()
        ) {
            Sheet sh = wb.createSheet("test");
            Row r = sh.createRow(0);

            for (int i = 0; i <= 50; i++) { // Off-by-one mistake
                Cell c = r.createCell(i);
                c.setCellValue(i + 1);

                CellStyle cs = wb.createCellStyle();
                cs.setFillBackgroundColor(IndexedColors.WHITE.index);
                cs.setFillPattern(FillPatternType.SOLID_FOREGROUND);
                cs.setFillForegroundColor(IndexedColors.LIGHT_BLUE.getIndex());
                c.setCellStyle(cs);

                if (i % 2 == 0) cs.setFillForegroundColor(IndexedColors.GREY_25_PERCENT.getIndex());
            }

            wb.write(os);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
