public class BaseCommand<T extends BasePayload> {
    String command;
    T payload;

    public BaseCommand(String command, T payload) {
        this.command = command;
        this.payload = payload;
    }
}

public class AddItemCommand extends BaseCommand<AddItemPayload> {
