import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

public class WindowsCommandRunner {

    private static List<String> runWindowsCommandAsRuntime(String command) {
        List<String> out = new ArrayList<>();

        String[] comm = {
                "C:\\Windows\\System32\\cmd.exe",
                "/S",
                "/K",
                "\"" + command + "\"",
                "&",
                "exit"
        };

        System.out.println("COMMAND: " + String.join(" ", comm));

        try {
            Process p = Runtime.getRuntime().exec(comm);
            BufferedReader reader = new BufferedReader(new InputStreamReader(p.getInputStream()));
            out = reader.lines().collect(Collectors.toList());

            int exitVal = p.waitFor();
            System.out.println("Exited with error code " + exitVal);

            p.destroy();
        } catch (Exception ex) {
            ex.printStackTrace();
            return null;
        }

        return out;
    }

    public static void main(String[] args) {
        List<String> output = runWindowsCommandAsRuntime("WMIC OS Get Caption,Version");
        if (output != null) {
            output.forEach(System.out::println);
        }
    }
}
