    @Inject
    public MyCamelRouteBuilder(MyJob myJob) {
        super();
        this.myJob = myJob;
    }

    @Override
    public void configure() {
        fromF("direct:%s", JOB_NAME)
            .routeId(JOB_NAME)
            .bean(myJob, JOB_METHOD_NAME)
