import org.springframework.http.MediaType;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.multipart.commons.CommonsMultipartFile;
import org.apache.commons.io.FileUtils;
import org.apache.commons.io.IOUtils;
import org.springframework.core.io.ByteArrayResource;
import org.springframework.core.io.InputStreamSource;
import java.io.*;

public class MultipartFileUtil {

    public static MultipartFile convertFileToMultipartFile(File file, String mimeType) {
        try {
            byte[] fileContent = FileUtils.readFileToByteArray(file);
            InputStreamSource inputStreamSource = new ByteArrayResource(fileContent);

            return new MultipartFile() {
                @Override
                public String getName() {
                    return file.getName();
                }

                @Override
                public String getOriginalFilename() {
                    return file.getName();
                }

                @Override
                public String getContentType() {
                    return mimeType;
                }

                @Override
                public boolean isEmpty() {
                    return file.length() == 0;
                }

                @Override
                public long getSize() {
                    return file.length();
                }

                @Override
                public byte[] getBytes() throws IOException {
                    return fileContent;
                }

                @Override
                public InputStream getInputStream() throws IOException {
                    return new ByteArrayInputStream(fileContent);
                }

                @Override
                public void transferTo(File dest) throws IOException {
                    FileUtils.writeByteArrayToFile(dest, fileContent);
                }
            };
        } catch (IOException e) {
            throw new RuntimeException("Failed to convert file to MultipartFile", e);
        }
    }
}
