import android.text.Spannable;
import android.text.SpannableString;
import android.text.style.AlignmentSpan;
import android.widget.TextView;
import android.text.Layout;

public class TextAlignUtil {
    public static void alignText(TextView textView) {
        String leftText = "Left";
        String rightText = "Right";
        String space = "    ";

        SpannableString finalString = new SpannableString(leftText + space + rightText);
        finalString.setSpan(new AlignmentSpan.Standard(Layout.Alignment.ALIGN_OPPOSITE), 
                leftText.length(), leftText.length() + rightText.length(), 
                Spannable.SPAN_EXCLUSIVE_EXCLUSIVE);

        textView.setText(finalString);
    }
}
