import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;

public class MavenCVEFetcher {
    public static void main(String[] args) {
        System.setProperty("https.proxyHost", "xxxx");
        System.setProperty("https.proxyPort", "xxxx");

        String address = "https://mvnrepository.com/artifact/log4j/apache-log4j-extras/1.2.17";
        String content = null;

        try {
            URL obj = new URL(address);
            HttpURLConnection con = (HttpURLConnection) obj.openConnection();
            con.setRequestMethod("GET");
            con.setRequestProperty("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Gecko/65.0.3325.181");
            con.setRequestProperty("Accept", "*/*");

            con.connect();

            BufferedReader br;

            if (con.getResponseCode() < 299) {
                br = new BufferedReader(new InputStreamReader(con.getInputStream(), StandardCharsets.UTF_16));
            } else {
                br = new BufferedReader(new InputStreamReader(con.getErrorStream(), StandardCharsets.UTF_8));
            }            

            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = br.readLine()) != null) {
                sb.append(line).append("\n");
            }
            br.close();

            content = sb.toString();

        } catch (Exception e) {
            e.printStackTrace();
        }

        System.out.println(content);
    }
}
