import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.control.TableCell;
import javafx.scene.control.TableColumn;
import javafx.scene.control.TableView;
import javafx.scene.text.Text;
import javafx.stage.Stage;

import java.util.List;

public class JavaFxTest extends Application {

    public static class FilePath {
        private final String path;

        public FilePath(String path) {
            this.path = path;
        }

        public String getPath() {
            return path;
        }
    }

    @Override
    public void start(Stage primaryStage) {
        TableView<FilePath> tableView = new TableView<>();

        TableColumn<FilePath, String> pathColumn = new TableColumn<>("Path");
        pathColumn.setPrefWidth(200);
        pathColumn.setCellValueFactory(data -> new javafx.beans.property.SimpleStringProperty(data.getValue().getPath()));

        pathColumn.setCellFactory(column -> new TableCell<>() {
            private final Text text = new Text();

            @Override
            protected void updateItem(String item, boolean empty) {
                super.updateItem(item, empty);
                if (empty || item == null) {
                    setGraphic(null);
                } else {
                    String trimmedPath = item;
                    if (trimmedPath.length() > 20) {
                        trimmedPath = ".." + trimmedPath.substring(trimmedPath.length() - 18);
                    }
                    text.setText(trimmedPath);
                    setGraphic(text);
                }
            }
        });

        tableView.getColumns().add(pathColumn);
        tableView.getItems().addAll(List.of(
            new FilePath("/usr/local/bin/someverylongdirectoryname/file.txt"),
            new FilePath("/usr/local/bin/someverylongdirectoryname/file2.txt")
        ));

        primaryStage.setScene(new Scene(tableView, 300, 200));
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}
