import android.graphics.Color;
import android.os.Bundle;
import androidx.appcompat.app.AppCompatActivity;
import com.github.mikephil.charting.charts.LineChart;
import com.github.mikephil.charting.components.Legend;
import com.github.mikephil.charting.data.Entry;
import com.github.mikephil.charting.data.LineData;
import com.github.mikephil.charting.data.LineDataSet;
import com.github.mikephil.charting.interfaces.datasets.ILineDataSet;
import java.util.ArrayList;
import java.util.List;

public class ChartActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_chart);

        LineChart lineChart = findViewById(R.id.lineChart);

        List<Entry> values1 = new ArrayList<>();
        List<Entry> values2 = new ArrayList<>();

        for (int i = 0; i < 10; i++) {
            values1.add(new Entry(i, (float) Math.sin(i)));
            values2.add(new Entry(i, (float) Math.cos(i)));
        }

        LineDataSet dataSet1 = new LineDataSet(values1, "Series 1");
        LineDataSet dataSet2 = new LineDataSet(values2, "Series 2");

        dataSet1.setColor(Color.BLUE);
        dataSet1.setCircleColor(Color.BLUE);

        dataSet2.setColor(Color.RED);
        dataSet2.setCircleColor(Color.RED);

        List<ILineDataSet> dataSets = new ArrayList<>();
        dataSets.add(dataSet1);
        dataSets.add(dataSet2);

        LineData data = new LineData(dataSets);
        lineChart.setData(data);

        Legend legend = lineChart.getLegend();
        legend.setEnabled(true);

        lineChart.invalidate();
    }
}
