import javafx.application.Application;
import javafx.scene.Group;
import javafx.scene.PerspectiveCamera;
import javafx.scene.Scene;
import javafx.scene.input.MouseEvent;
import javafx.scene.paint.Color;
import javafx.scene.paint.PhongMaterial;
import javafx.scene.shape.Box;
import javafx.scene.shape.CullFace;
import javafx.scene.shape.DrawMode;
import javafx.stage.Stage;

public class OutlineEffect extends Application {

    @Override
    public void start(Stage primaryStage) {
        Box box = new Box(100, 100, 100);
        PhongMaterial material = new PhongMaterial();
        material.setDiffuseColor(Color.DARKGRAY);
        box.setMaterial(material);

        Box outline = new Box(102, 102, 102);
        outline.setMaterial(new PhongMaterial(Color.YELLOW));
        outline.setDrawMode(DrawMode.LINE);
        outline.setCullFace(CullFace.NONE);
        outline.setVisible(false);

        Group group = new Group(outline, box);

        box.addEventHandler(MouseEvent.MOUSE_CLICKED, event -> {
            outline.setVisible(!outline.isVisible());
            event.consume();
        });

        Scene scene = new Scene(group, 600, 400, true);
        scene.setFill(Color.LIGHTGRAY);
        scene.setCamera(new PerspectiveCamera());

        primaryStage.setScene(scene);
        primaryStage.setTitle("3D Outline Effect");
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}
