public class AuthController {
    private final AuthService authService;
    private final UserRepository userRepository;
    private final UserTenantRepository userTenantRepository;

    @PostMapping("/signin")
    public ResponseEntity<?> authenticateUser(
            @RequestAttribute(required = false) String subdomain, 
            @Valid @RequestBody LoginRequest loginRequest) {

        if (subdomain == null || !userTenantRepository.existsByUsernameAndSubdomain(subdomain, loginRequest.getUsername())) {
            return ResponseEntity.badRequest().body(new MessageResponse("Unauthorized access"));
        }

        return ResponseEntity.ok(authService.authenticateUser(subdomain, loginRequest));
    }
}
