import java.util.*;
import java.util.stream.*;

class Employee {
    String id, name, city;

    Employee(String id, String name, String city) {
        this.id = id;
        this.name = name;
        this.city = city;
    }

    public String getId() { return id; }
    public String getName() { return name; }
    public String getCity() { return city; }
    public void setCity(String city) { this.city = city; }

    @Override
    public String toString() {
        return "Employee(id=" + id + ", name=" + name + ", city=" + city + ")";
    }
}

class Person {
    String id, city;

    Person(String id, String city) {
        this.id = id;
        this.city = city;
    }

    public String getId() { return id; }
    public String getCity() { return city; }
}

public class MergeLists {
    public static void main(String[] args) {
        List<Employee> employeeList = Stream.of(
                new Employee("100", "Alex", ""),
                new Employee("200", "Rida", ""),
                new Employee("300", "Ganga", ""))
            .collect(Collectors.toList());

        List<Person> personList = Stream.of(
                new Person("100", "Atlanta"),
                new Person("300", "Boston"),
                new Person("400", "Pleasanton"))
            .collect(Collectors.toList());

        Map<String, Employee> employeeMap = employeeList.stream()
                .collect(Collectors.toMap(Employee::getId, e -> e));

        personList.forEach(p -> employeeMap.computeIfAbsent(p.getId(), id -> new Employee(id, null, p.getCity()))
                                           .setCity(p.getCity()));

        List<Employee> mergedList = new ArrayList<>(employeeMap.values());

        System.out.println(mergedList);
    }
}
