from sqlalchemy.orm import Session
from fastapi import FastAPI, Depends, HTTPException
from typing import List
import models, schemas, crud
from database import SessionLocal, engine

models.Base.metadata.create_all(bind=engine)

app = FastAPI()

def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

@app.post("/users/", response_model=schemas.User)
def create_user(user: schemas.UserCreate, db: Session = Depends(get_db)):
    db_user = crud.get_user_by_email(db, email=user.email)
    if db_user:
        raise HTTPException(status_code=400, detail="Email already exists")
    return crud.create_user(db=db, user=user)

@app.get("/users/", response_model=List[schemas.User])
def read_users(skip: int = 0, limit: int = 100, db: Session = Depends(get_db)):
    return crud.get_users(db, skip=skip, limit=limit)

@app.get("/users/{user_id}", response_model=schemas.User)
def read_user(user_id: int, db: Session = Depends(get_db)):
    db_user = crud.get_user(db, user_id=user_id)
    if db_user is None:
        raise HTTPException(status_code=404, detail="User not found")
    return db_user

@app.post("/users/{user_id}/items/", response_model=schemas.Item)
def create_item_for_user(user_id: int, item: schemas.ItemCreate, db: Session = Depends(get_db)):
    return crud.create_user_item(db=db, item=item, user_id=user_id)

@app.get("/items/", response_model=List[schemas.Item])
def read_items(skip: int = 0, limit: int = 100, db: Session = Depends(get_db)):
    return crud.get_items(db, skip=skip, limit=limit)
,"[""from sqlalchemy.orm import Session\r\nfrom fastapi import FastAPI, Depends, HTTPException\r\nfrom typing import List\r\nimport models, schemas, crud\r\nfrom database import SessionLocal, engine\r\n\r\nmodels.Base.metadata.create_all(bind=engine)\r\n\r\napp = FastAPI()\r\n\r\ndef get_db():\r\n    db = SessionLocal()\r\n    try:\r\n        yield db\r\n    finally:\r\n        db.close()\r\n\r\n@app.post(""/users/"", response_model=schemas.User)\r\ndef create_user(user: schemas.UserCreate, db: Session = Depends(get_db)):\r\n    db_user = crud.get_user_by_email(db, email=user.email)\r\n    if db_user:\r\n        raise HTTPException(status_code=400, detail=""Email already exists"")\r\n    return crud.create_user(db=db, user=user)\r\n\r\n@app.get(""/users/"", response_model=List[schemas.User])\r\ndef read_users(skip: int = 0, limit: int = 100, db: Session = Depends(get_db)):\r\n    return crud.get_users(db, skip=skip, limit=limit)\r\n\r\n@app.get(""/users/{user_id}"", response_model=schemas.User)\r\ndef read_user(user_id: int, db: Session = Depends(get_db)):\r\n    db_user = crud.get_user(db, user_id=user_id)\r\n    if db_user is None:\r\n        raise HTTPException(status_code=404, detail=""User not found"")\r\n    return db_user\r\n\r\n@app.post(""/users/{user_id}/items/"", response_model=schemas.Item)\r\ndef create_item_for_user(user_id: int, item: schemas.ItemCreate, db: Session = Depends(get_db)):\r\n    return crud.create_user_item(db=db, item=item, user_id=user_id)\r\n\r\n@app.get(""/items/"", response_model=List[schemas.Item])\r\ndef read_items(skip: int = 0, limit: int = 100, db: Session = Depends(get_db)):\r\n    return crud.get_items(db, skip=skip, limit=limit)\r\n""]",0

from pydantic import BaseModel, validator

class Window(BaseModel):
    size: tuple[int, int]

    @validator("size", pre=True)
    def parse_size(cls, value):
        if isinstance(value, str):
            parts = value.split("x")
            if len(parts) != 2:
                raise ValueError("Invalid size format")
            return int(parts[0]), int(parts[1])
        return value

fields = {'size': '1920x1080'}
window = Window(**fields)
print(window)
