import os
from fastapi import APIRouter, Depends, Security, HTTPException

def api_key(api_key_header: str = Security(api_key_header_auth)):
    env = os.getenv("ENV", "production")
    if env == "localhost":
        return
    if api_key_header != API_KEY:
        raise HTTPException(
            status_code=401,
            detail="Invalid API Key",
        )

router = APIRouter(
    prefix="/v2/test",
    tags=["helloWorld"],
    dependencies=[Depends(api_key) if os.getenv("ENV") != "localhost" else None],
    responses={404: {"description": "Not found"}}
)
