import polars as pl
from rich.progress import Progress

df = pl.DataFrame(
    {
        "team": ["A", "A", "A", "B", "B", "C"],
        "conference": ["East", "East", "East", "West", "West", "East"],
        "points": [11, 8, 10, 6, 6, 5],
        "rebounds": [7, 7, 6, 9, 12, 8]
    }
)

def pl_progress_applier(func, x, task_id, progress, **kwargs):
    progress.update(task_id, advance=1)
    return func(x=x, **kwargs)

def pl_groupby_progress_apply(data, group_by, func, drop_cols=[], **kwargs):
    with Progress() as progress:
        num_groups = len(data.select(group_by).unique())
        task_id = progress.add_task('Applying', total=num_groups)
        return (
            data
                .group_by(group_by)
                .map_groups(lambda x: pl_progress_applier(
                    func, x.drop(drop_cols), task_id, progress, **kwargs)
                )
        )

def custom_func(x):
    return x.select(pl.col('points').mean())

result = pl_groupby_progress_apply(
    data=df,
    group_by='team',
    func=custom_func
)
print(result)
,"[""import polars as pl\r\nfrom rich.progress import Progress\r\n\r\ndf = pl.DataFrame(\r\n    {\r\n        ""team"": [""A"", ""A"", ""A"", ""B"", ""B"", ""C""],\r\n        ""conference"": [""East"", ""East"", ""East"", ""West"", ""West"", ""East""],\r\n        ""points"": [11, 8, 10, 6, 6, 5],\r\n        ""rebounds"": [7, 7, 6, 9, 12, 8]\r\n    }\r\n)\r\n\r\ndef pl_progress_applier(func, x, task_id, progress, **kwargs):\r\n    progress.update(task_id, advance=1)\r\n    return func(x=x, **kwargs)\r\n\r\ndef pl_groupby_progress_apply(data, group_by, func, drop_cols=[], **kwargs):\r\n    with Progress() as progress:\r\n        num_groups = len(data.select(group_by).unique())\r\n        task_id = progress.add_task('Applying', total=num_groups)\r\n        return (\r\n            data\r\n                .group_by(group_by)\r\n                .map_groups(lambda x: pl_progress_applier(\r\n                    func, x.drop(drop_cols), task_id, progress, **kwargs)\r\n                )\r\n        )\r\n\r\ndef custom_func(x):\r\n    return x.select(pl.col('points').mean())\r\n\r\nresult = pl_groupby_progress_apply(\r\n    data=df,\r\n    group_by='team',\r\n    func=custom_func\r\n)\r\nprint(result)\r\n""]",0

