from fastapi import FastAPI, Request
from starlette.middleware.base import BaseHTTPMiddleware
from starlette.responses import Response
import json

app = FastAPI()

class CustomMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        response = await call_next(request)

        body = b""
        async for chunk in response.body_iterator:
            body += chunk

        data = {}
        try:
            data["data"] = json.loads(body.decode())
        except json.JSONDecodeError:
            data["data"] = {}

        data["metadata"] = {
            "some_data_key_1": "some_data_value_1",
            "some_data_key_2": "some_data_value_2",
            "some_data_key_3": "some_data_value_3"
        }

        body = json.dumps(data, indent=2).encode("utf-8")

        return Response(content=body, status_code=response.status_code, media_type=response.media_type)

app.add_middleware(CustomMiddleware)

@app.get("/")
async def read_root():
    return {"message": "Hello World"}

@app.get("/item")
async def read_item():
    return {"item": "This is an item"}
