        String[] timestamps = {
                "2023-10-05T15:14:29.123456789Z", // 9 digits
                "2023-10-05T15:14:29.12345678Z",  // 8 digits
                "2023-10-05T15:14:29.1234567Z",   // 7 digits
                "2023-10-05T15:14:29.123456Z",    // 6 digits
