  public static void main(String[] args) throws Throwable {
    try (var arena = Arena.ofConfined()) {
      var array = new LargeArray<Point>(arena, 10L, Point.DESCRIPTOR);

      // populate array
      for (long i = 0; i < array.length(); i++) {
        var point = new Point(arena);
        point.setX((int) i);
        point.setY((int) i * 2);
        array.set(i, point);
