      // show modification of element in array
      var midPoint = array.get(5L);
      midPoint.setX(42);
      midPoint.setY(117);

      // print array contents
      for (long i = 0; i < array.length(); i++) {
        System.out.printf("array[%d] = %s%n", i, array.get(i));
      }
    }
  }
