        try (CSVReader reader = new CSVReaderBuilder(new InputStreamReader(Objects.requireNonNull(TestMain.class.getResourceAsStream(filePath))))
                .withCSVParser(new CSVParserBuilder().withSeparator('\t').build())
                .build()) {
