  traverseBodyElements(documentToAppend.getBodyElements(), resultDocument);
  documentToAppend.close();
  FileOutputStream out = new FileOutputStream(resultFilePath);
  resultDocument.write(out);
  out.close();
  resultDocument.close();
 }

