        array[3] = 1;
        array[4] = 3;
        array[5] = 0;
        array[6] = 9;
        array[7] = 7;

        int index = 0;
        String ans = null;
        boolean yn;
        System.out.print("Search for? ");
        int searching = scanner.nextInt();

        for(int i=0; i<array.length; i++) {
            if (searching == array[i]) {
                index = i;
                ans = searching + " is at index " + index + ".";
                yn = true;
                break;
            } else {
                ans = searching + " was not found.";
                yn = false;
            }
        }
        System.out.println(ans);
    }
